    { pregunta: "¿Qué protocolo protege la comunicación web mediante cifrado?", opciones: ["HTTPS", "HTTP-IMAGE", "WEB-SECURE-FILE"], correcta: 0, explicacion: "HTTPS (HTTP Secure) cifra los datos transmitidos entre el navegador y el servidor." },
    { pregunta: "¿Qué característica ayuda a proteger una cuenta además de la contraseña?", opciones: ["Autenticación multifactor", "Cambiar el nombre de usuario", "Aumentar el tamaño de la pantalla"], correcta: 0, explicacion: "La autenticación multifactor (MFA) añade una capa extra de seguridad, como un código enviado al teléfono." },
    { pregunta: "¿Qué es una contraseña segura?", opciones: ["Una contraseña larga, única y difícil de adivinar", "El nombre de la persona", "La palabra 123456"], correcta: 0, explicacion: "Una buena contraseña combina mayúsculas, minúsculas, números y símbolos, y no es obvia." },
    { pregunta: "¿Qué es el phishing?", opciones: ["Un engaño para obtener información confidencial", "Un método para comprimir imágenes", "Una herramienta para crear bases de datos"], correcta: 0, explicacion: "El phishing es una estafa donde se hacen pasar por alguien de confianza para robar datos." },
    { pregunta: "¿Qué es el malware?", opciones: ["Software diseñado para causar daño o realizar acciones no autorizadas", "Un programa para editar documentos", "Un sistema para mejorar la velocidad de una página"], correcta: 0, explicacion: "Malware es un término general para virus, troyanos, spyware y otros programas maliciosos." },
    { pregunta: "¿Qué es una inyección SQL?", opciones: ["Una vulnerabilidad que permite introducir instrucciones SQL no autorizadas", "Una forma de cifrar fotografías", "Un método para diseñar formularios"], correcta: 0, explicacion: "Es un ataque en el que el usuario malicioso introduce código SQL en campos de entrada para manipular la base de datos." },
    { pregunta: "¿Qué significa XSS?", opciones: ["Cross-Site Scripting", "Extra Secure System", "XML Server Storage"], correcta: 0, explicacion: "XSS (Cross-Site Scripting) es una vulnerabilidad que permite inyectar scripts maliciosos en sitios web." },
    { pregunta: "¿Qué puede provocar una vulnerabilidad XSS?", opciones: ["Ejecutar contenido malicioso en el navegador de otra persona", "Aumentar la memoria del servidor", "Mejorar la calidad de una imagen"], correcta: 0, explicacion: "El atacante puede robar cookies, sesiones o redirigir a páginas falsas a través del navegador de la víctima." },
    { pregunta: "¿Qué principio recomienda asignar solo los permisos necesarios?", opciones: ["Principio de mínimo privilegio", "Principio de acceso total", "Principio de contraseña pública"], correcta: 0, explicacion: "El principio de mínimo privilegio dicta que cada usuario debe tener solo el acceso indispensable para su trabajo." },
    { pregunta: "¿Qué es una actualización de seguridad?", opciones: ["Una modificación que corrige errores o vulnerabilidades", "Un cambio de nombre de una aplicación", "Una copia de una imagen"], correcta: 0, explicacion: "Los parches de seguridad cierran brechas que los atacantes podrían aprovechar." },
    { pregunta: "¿Qué debe hacerse con las contraseñas almacenadas en una aplicación?", opciones: ["Guardarlas protegidas mediante técnicas adecuadas de hash", "Guardarlas en texto visible", "Publicarlas dentro del código"], correcta: 0, explicacion: "Las contraseñas nunca se guardan en texto plano; se usa hash con 'sal' (salt) para protegerlas." },
    { pregunta: "¿Qué es una copia de seguridad?", opciones: ["Una copia de los datos que permite recuperarlos si se pierden o dañan", "Un tipo de virus informático", "Una contraseña temporal"], correcta: 0, explicacion: "Los respaldos (backups) son esenciales para la continuidad del negocio ante fallos o ataques." }
