  sw: [
    { pregunta: "¿Qué es un Service Worker?", opciones: ["Un script que puede funcionar entre una aplicación web, el navegador y la red", "Un archivo exclusivo para cambiar colores", "Un programa para editar imágenes"], correcta: 0, explicacion: "Un Service Worker es un script que se ejecuta en segundo plano y actúa como intermediario de red." },
    { pregunta: "¿En qué contexto funcionan normalmente los Service Workers?", opciones: ["En un contexto seguro mediante HTTPS", "Únicamente mediante FTP", "Solo cuando no existe conexión a internet"], correcta: 0, explicacion: "Por razones de seguridad, los Service Workers solo se ejecutan en conexiones seguras (HTTPS)." },
    { pregunta: "¿Qué excepción se permite normalmente para desarrollar Service Workers sin HTTPS?", opciones: ["localhost", "Cualquier dominio desconocido", "Archivos enviados por correo electrónico"], correcta: 0, explicacion: "Para desarrollo local, los navegadores permiten usar Service Workers en 'localhost' sin necesidad de HTTPS." },
    { pregunta: "¿Qué método se utiliza para registrar un Service Worker?", opciones: ["navigator.serviceWorker.register()", "window.registerWorkerFile()", "serviceWorker.startScript()"], correcta: 0, explicacion: "El método register() del objeto serviceWorker es el estándar para iniciar el proceso." },
    { pregunta: "¿Cuál es el primer evento importante del ciclo de vida de un Service Worker?", opciones: ["install", "delete", "render"], correcta: 0, explicacion: "El evento 'install' se dispara cuando el navegador descarga e intenta instalar el Service Worker." },
    { pregunta: "¿Para qué se utiliza normalmente el evento install?", opciones: ["Para preparar recursos y almacenarlos en caché", "Para cerrar el navegador", "Para eliminar todos los usuarios"], correcta: 0, explicacion: "En el evento install se suelen precargar los archivos estáticos en la caché." },
    { pregunta: "¿Qué evento ocurre después de la instalación?", opciones: ["activate", "compile", "connect"], correcta: 0, explicacion: "Una vez instalado, el Service Worker pasa al evento 'activate' para tomar el control." },
    { pregunta: "¿Para qué se utiliza normalmente el evento activate?", opciones: ["Para activar el Service Worker y limpiar cachés antiguas", "Para crear archivos CSS automáticamente", "Para cambiar el idioma del navegador"], correcta: 0, explicacion: "En 'activate' es común eliminar versiones anteriores de la caché para no ocupar espacio innecesario." },
    { pregunta: "¿Qué evento permite interceptar solicitudes de red?", opciones: ["fetch", "requestPage", "networkStart"], correcta: 0, explicacion: "El evento 'fetch' intercepta todas las peticiones de red que hace la aplicación." },
    { pregunta: "¿Qué API permite guardar respuestas y recursos en caché?", opciones: ["Cache Storage API", "PageMemory API", "BrowserFiles API"], correcta: 0, explicacion: "La Cache Storage API permite almacenar pares de solicitudes y respuestas (Request/Response)." },
    { pregunta: "¿Qué beneficio puede proporcionar un Service Worker?", opciones: ["Permitir que una aplicación funcione parcialmente sin conexión", "Aumentar físicamente la memoria del dispositivo", "Crear un servidor sin código"], correcta: 0, explicacion: "Al servir archivos desde la caché, la app puede cargar y funcionar parcialmente sin internet." },
    { pregunta: "¿Qué función permite mantener una operación activa hasta que termine una promesa?", opciones: ["event.waitUntil()", "event.keepOpenForever()", "service.waitPromise()"], correcta: 0, explicacion: "waitUntil() le dice al navegador que no detenga el Service Worker hasta que la promesa se resuelva." },
    { pregunta: "¿Qué función se utiliza en un evento fetch para responder una solicitud personalizada?", opciones: ["event.respondWith()", "event.sendResponseNow()", "fetch.returnPage()"], correcta: 0, explicacion: "respondWith() permite devolver una respuesta personalizada (desde caché o red) para la petición interceptada." },
    { pregunta: "¿Qué puede hacer un Service Worker con una solicitud interceptada?", opciones: ["Responder desde la caché, desde la red o mediante otra lógica", "Cambiar el hardware del dispositivo", "Modificar el sistema operativo completo"], correcta: 0, explicacion: "Tienes control total para decidir de dónde proviene la respuesta a esa solicitud." },
    { pregunta: "¿Qué puede ocurrir cuando se actualiza un Service Worker?", opciones: ["Se instala una nueva versión y puede reemplazar a la anterior después de activarse", "Se borran automáticamente todos los archivos del servidor", "Se desinstala el navegador"], correcta: 0, explicacion: "El navegador detecta el cambio, instala la nueva versión y la activa cuando es seguro hacerlo." }
  ],

