    { pregunta: "¿Cómo se enlaza un manifiesto desde un documento HTML?", opciones: ["&lt;link rel=\"manifest\" href=\"/manifest.json\"&gt;", "&lt;manifest src=\"/manifest.json\"&gt;", "&lt;script manifest=\"/manifest.json\"&gt;&lt;/script&gt;"], correcta: 0, explicacion: "Se utiliza la etiqueta &lt;link&gt; con el atributo rel=\"manifest\" dentro del &lt;head&gt;." },
    { pregunta: "¿Para qué sirve principalmente el manifiesto en una PWA?", opciones: ["Para describir cómo debe instalarse y mostrarse la aplicación", "Para reemplazar todo el código del servidor", "Para crear consultas SQL automáticamente"], correcta: 0, explicacion: "Es el archivo que permite que el sistema operativo instale la web como si fuera una aplicación nativa." },
    { pregunta: "¿Qué propiedad puede indicar el idioma o dirección del texto de la aplicación?", opciones: ["lang y dir", "language_code y text_direction_css", "locale_style y writing_mode_app"], correcta: 0, explicacion: "'lang' define el idioma (ej. 'es') y 'dir' la dirección del texto ('ltr' o 'rtl')." }
